 stats=r["metrics"]["businessSigns"];assert r["version"]=="1.6.129";assert stats["catalogueGeneratedAt"]==data["generatedAt"];assert not r["errors"] and not r["failed"] and not r["rejected"];assert stats["renderedNames"]==data["coverage"]["placementCandidates"]
